namespace CheckoutPricing.UnitTest.Features.Discount;

public class CalculateLoyaltyDiscountAcceptanceTests
{
    private static void AssertQuote(int subtotal, LoyaltyTier tier, string? code, int discount, int total)
    {
        var quote = new CalculateLoyaltyDiscount().Handle(new CalculateLoyaltyDiscountQuery(subtotal, tier, code));
        Assert.Equal(discount, quote.DiscountCents);
        Assert.Equal(total, quote.TotalCents);
    }

    [Theory]
    [InlineData(LoyaltyTier.Bronze, 500, 9500)]
    [InlineData(LoyaltyTier.Silver, 1000, 9000)]
    [InlineData(LoyaltyTier.Gold, 1500, 8500)]
    public void S1_MemberReceivesTheLoyaltyDiscountOfTheirTier(LoyaltyTier tier, int discount, int total) // Member receives the loyalty discount of their tier
        => AssertQuote(10000, tier, null, discount, total);

    [Theory]
    [InlineData(20000, LoyaltyTier.Gold, 2000, 18000)]
    [InlineData(30000, LoyaltyTier.Silver, 2000, 28000)]
    [InlineData(12000, LoyaltyTier.Gold, 1800, 10200)]
    public void S2_LoyaltyDiscountNeverExceeds20Euros(int subtotal, LoyaltyTier tier, int discount, int total) // The loyalty discount never exceeds 20.00 EUR
        => AssertQuote(subtotal, tier, null, discount, total);

    [Theory]
    [InlineData(2999, 0, 2999)]
    [InlineData(3000, 450, 2550)]
    public void S3_NoLoyaltyDiscountUnder30Euros(int subtotal, int discount, int total) // No loyalty discount under a 30.00 EUR subtotal
        => AssertQuote(subtotal, LoyaltyTier.Gold, null, discount, total);

    [Theory]
    [InlineData(10000, LoyaltyTier.Silver, 1500, 8500)]
    [InlineData(2000, LoyaltyTier.Bronze, 500, 1500)]
    public void S4_Welcome5TakesFiveEurosOffAfterTheLoyaltyDiscount(int subtotal, LoyaltyTier tier, int discount, int total) // The WELCOME5 promo code takes 5.00 EUR off after the loyalty discount
        => AssertQuote(subtotal, tier, "WELCOME5", discount, total);

    [Theory]
    [InlineData(20000, LoyaltyTier.Gold, 2500, 17500)]
    [InlineData(30000, LoyaltyTier.Silver, 2500, 27500)]
    public void S5_CapAppliesToLoyaltyDiscountOnlyNeverToWelcome5(int subtotal, LoyaltyTier tier, int discount, int total) // The cap applies to the loyalty discount only, never to WELCOME5
        => AssertQuote(subtotal, tier, "WELCOME5", discount, total);

    [Theory]
    [InlineData("welcome5")]
    [InlineData("Welcome5")]
    public void S6_PromoCodesIgnoreCase(string code) // Promo codes ignore case
        => Assert.Equal(1500, new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Silver, code)).DiscountCents);

    [Theory]
    [InlineData(10000, LoyaltyTier.Silver, 1900, 8100)]
    [InlineData(30000, LoyaltyTier.Bronze, 3000, 27000)]
    [InlineData(2000, LoyaltyTier.Gold, 200, 1800)]
    public void S7_Summer10TakesTenPercentOffWhatIsLeftAtMost15Euros(int subtotal, LoyaltyTier tier, int discount, int total) // The SUMMER10 promo code takes 10 % off what is left, at most 15.00 EUR
        => AssertQuote(subtotal, tier, "SUMMER10", discount, total);

    [Fact]
    public void S8_UnknownPromoCodeIsIgnored() // An unknown promo code is ignored
        => AssertQuote(10000, LoyaltyTier.Silver, "SPRING", 1000, 9000);

    [Theory]
    [InlineData(10000, 2000, 8000)]
    [InlineData(5000, 1000, 4000)]
    [InlineData(20000, 2000, 18000)]
    public void S9_PlatinumMembersReceiveA20PercentLoyaltyDiscount(int subtotal, int discount, int total) // Platinum members receive a 20 % loyalty discount
        => AssertQuote(subtotal, LoyaltyTier.Platinum, null, discount, total);

    [Theory]
    [InlineData(400, LoyaltyTier.Bronze, 400)]
    [InlineData(300, LoyaltyTier.Gold, 300)]
    public void S10_DiscountNeverExceedsTheSubtotal(int subtotal, LoyaltyTier tier, int discount) // The discount never exceeds the subtotal
        => AssertQuote(subtotal, tier, "WELCOME5", discount, 0);
}

